export async function RevenueChart() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json() as { revenue: { month: string; amount: number }[] }
  return (
    <div className="chart">
      <h2>Revenue</h2>
      <ul>
        {data.revenue.map((item) => (
          <li key={item.month}>
            {item.month}: ${item.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function RevenueChartSkeleton() {
  return (
    <div className="chart animate-pulse">
      <h2>Revenue</h2>
      <div className="h-32 bg-gray-200 rounded" />
    </div>
  )
}

export async function CardStats() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json() as { totalRevenue: number; totalInvoices: number }
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${data.totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{data.totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card animate-pulse">
        <div className="h-4 w-24 bg-gray-200 rounded" />
        <div className="h-6 w-32 bg-gray-200 rounded mt-2" />
      </div>
      <div className="card animate-pulse">
        <div className="h-4 w-24 bg-gray-200 rounded" />
        <div className="h-6 w-16 bg-gray-200 rounded mt-2" />
      </div>
    </div>
  )
}

export async function LatestInvoices() {
  const res = await fetch('https://api.example.com/dashboard')
  const data = await res.json() as { invoices: { id: string; name: string; amount: number }[] }
  return (
    <div className="invoices">
      <h2>Latest Invoices</h2>
      <ul>
        {data.invoices.map((invoice) => (
          <li key={invoice.id}>
            {invoice.name} - ${invoice.amount.toLocaleString()}
          </li>
        ))}
      </ul>
    </div>
  )
}

export function LatestInvoicesSkeleton() {
  return (
    <div className="invoices animate-pulse">
      <h2>Latest Invoices</h2>
      <div className="space-y-2">
        <div className="h-4 bg-gray-200 rounded" />
        <div className="h-4 bg-gray-200 rounded" />
        <div className="h-4 bg-gray-200 rounded" />
      </div>
    </div>
  )
}
